"""Decoded event records consumed by HttpClient in offline mode."""
from dataclasses import dataclass


class SendError(Exception):
    pass


@dataclass
class HeadersReceived:
    stream_id: int
    headers: list
    stream_ended: bool


@dataclass
class DataReceived:
    stream_id: int
    data: object
    stream_ended: bool


@dataclass
class ConnectionTerminated:
    error_code: int = 0
    reason_phrase: str = 'capture close'
